import json,csv,collections
from pathlib import Path
P=Path('work/parts')
talks=[];items=[];problems=[];corrections=[];evidence=[]
def talk(r,date,speaker,pages,title,summary):
 talks.append(dict(record=r,date=date,speaker=speaker,pages=pages,title=title,kind='talk',summary=summary))
def item(r,pages,kind,title,notes,statement,refs,area='geometry',cl='E',reconstruction='',fate='',status='',correct='correct',match='exact',verification='read the result',development='none',problem='',worth='',confidence='high'):
 n=1+sum(x['record']==r for x in items)
 if not fate: fate="Established before this talk. " + "\\citep{"+",".join(refs)+"}"
 if not status: status=r"""As of 9 November 2026, this is an established result in the stated setting; the notebook occurrence does not leave a separate open problem."""
 items.append(dict(id=f'1965-{r}.{n}',record=r,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cl},fate=fate,present_status=status,literal_correctness=correct,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=refs,confidence=confidence,area=area))
def corr(page,place,old,new,evidence,applies='both'):
 corrections.append(dict(page=page,place=place,transcription_reads=old,should_read=new,evidence=evidence,applies_to=applies))
def ev(query,url,level,result,locators='',record=''):
 evidence.append(dict(query=query,url=url,check_level=level,result=result,locators=locators,records=record,status_date='2026-11-09'))
def save():
 for name,obj in [('talks',talks),('items',items),('problems',problems),('evidence',evidence)]:
  (P/f'middle_{name}.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
 with (P/'middle_corrections.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to']);w.writeheader();w.writerows(corrections)

# 69. Matsaev: independent source boundaries established from scans 108--109.
talk(69,'1965-11-15','V. I. Matsaev','P000108-P000109','The Atiyah--Bott fixed-point formula',r"""The record begins at the dated Matsaev heading on P000108, after the preceding discussion of derived functors, and ends before Kazhdan on P000109. It gives the cohomological Lefschetz number of a geometric endomorphism of an elliptic complex, complex-power regularization, and the transverse-distribution interpretation of the local fixed-point contributions. The independent near-contemporary match is Bott's November 1965 Bourbaki exposition, which itself cites the 1964 Harvard notes. \citep{bott1966report}""")
item(69,'P000108','definition','Lefschetz number of a geometric endomorphism',r"""For \(\cdots\to\Gamma(E_i)\xrightarrow d\Gamma(E_{i+1})\to\cdots\), the maps \(T_i\) commute with \(d\); the notes define \(L(T,E)=\sum_i(-1)^i\operatorname{tr}T_i^*\).""",r"""Let \(X\) be a compact smooth manifold without boundary, \((E_\bullet,d)\) a finite elliptic complex, and \(T_i\) continuous endomorphisms of its section spaces satisfying \(d_iT_i=T_{i+1}d_i\). Ellipticity makes \(H^i(E_\bullet)\) finite dimensional. The Lefschetz number is the alternating trace of the induced maps on these cohomology spaces.""", ['bott1966report'],area='elliptic operators and fixed points',correct='correct with missing hypotheses',reconstruction=r"""Compactness, absence of boundary, finiteness and ellipticity are the analytic setting required by the proof, rather than words repeated at this heading.""")
item(69,'P000108','theorem','Transverse fixed-point formula',r"""The local term is \(\sigma(\rho)=\sum_i(-1)^i\operatorname{Sp}\varphi_i(\rho)/|\det(1-I_f(\rho))|\); the total is a sum over fixed points.""",r"""Assume additionally that \(T_i s(x)=\varphi_i(x)s(f(x))\), where \(f:X\to X\) is smooth and \(\varphi_i:f^*E_i\to E_i\) intertwines the complex. If every fixed point \(\rho\) is transverse, equivalently \(\det(I-df_\rho)\ne0\), then \[L(T,E)=\sum_{f(\rho)=\rho}\frac{\sum_i(-1)^i\operatorname{tr}\varphi_i(\rho)}{|\det(I-df_\rho)|}.\] There are finitely many such points on compact \(X\).""",['bott1966report'],area='elliptic operators and fixed points',correct='correct with missing hypotheses',reconstruction=r"""The geometric form of \(T\), transversality and the fixed-point index of the outer sum are supplied explicitly. The denominator belongs to the real smooth formula; holomorphic variants package numerator and denominator differently.""",fate=r"""Bott's Expos\'e 295 states this formula and dates the lecture to November 1965; its bibliography identifies the Atiyah--Bott Harvard notes of fall 1964. Thus later printing does not make the theorem new in this seminar. \citep{bott1966report}""")
item(69,'P000108','method','Kernel proof and its trace-class obstruction',r"""The notes call the formal proof trivial: \(L=\sum_i(-1)^i\operatorname{tr}T_i\), with kernel \(\varphi\delta(y-f(x))\); its diagonal gives the fixed-point sum.""",r"""The finite-dimensional Euler trace identity does not by itself justify traces on infinite-dimensional section spaces. For a transverse geometric endomorphism the distribution kernel restricts to the diagonal and defines a flat trace; its value is the displayed fixed-point sum. Ordinary operator trace need not exist. A smoothing or complex-power argument is required to identify the alternating flat trace with the cohomological trace.""",['bott1966report'],area='elliptic operators and fixed points',correct='correct with missing hypotheses',development='annotated',reconstruction=r"""The distinction between ordinary trace and diagonal distributional (flat) trace makes explicit the obstruction acknowledged by the subsequent regularization.""")
item(69,'P000108','construction','Complex-power regularization and eigenspace cancellation',r"""\(T_{i,z}=(1+\Box_i)^{-z}T_i\), \(\Box=d\delta+\delta d\). A displayed eigenseries lacks a trace on its finite-dimensional summands; the alternating trace is said to continue to all \(z\).""",r"""Choose metrics and the formal adjoints \(\delta\). For \(\operatorname{Re}z\) sufficiently large, \((1+\Box_i)^{-z}T_i\) is trace class, with trace \[\sum_\lambda(1+\lambda)^{-z}\operatorname{tr}(\pi_{i,\lambda}T_i\iota_{i,\lambda}).\] The eigenspace complexes at positive \(\lambda\) are acyclic, and their projected endomorphisms have vanishing alternating trace. The remaining harmonic-space trace equals \(L(T,E)\), so the supertrace is constant on its initial domain and extends as that constant.""", ['bott1966report'],area='elliptic operators and fixed points',correct='correct with missing hypotheses',reconstruction=r"""The finite-dimensional trace in the eigenseries and the projected chain map are explicit repairs. Commutation of \(T\) with \(d\) need not imply commutation with \(\Box\); the projection formulation avoids that unwarranted assumption.""",development='annotated')
item(69,'P000108','claim','Off-diagonal regularity and the value at zero',r"""The complex-power kernel is smooth away from the diagonal. With separated cutoffs \(\mu_1,\mu_2\), \(\mu_1(1+\Box)^{-z}\mu_2\) has a smooth kernel. At \(z=0\) the continued alternating trace is an integral as a number.""",r"""Complex powers of a positive elliptic operator have kernels smooth off the diagonal; localization by smooth cutoffs with disjoint supports is smoothing. Under the fixed-point transversality assumptions the regularized trace has the appropriate holomorphic continuation at zero and there equals the diagonal distributional trace. An unrestricted integral of the unsmoothed kernel is not being asserted.""",['bott1966report'],area='elliptic operators and fixed points',correct='correct with missing hypotheses',reconstruction=r"""The unreadable support condition is reconstructed as disjoint supports from both the kernel argument and Bott's regularization. The parenthetical name is identified bibliographically with Kotake--Narasimhan; the scan alone does not settle its letters.""",confidence='medium',match='partial')
item(69,'P000109','question','Multiplying distributions conormal to transverse submanifolds',r"""When can distributions singular on transverse submanifolds be multiplied? A sufficient example is \(P\delta_S\), with \(P\) pseudodifferential; the notes prescribe special smooth approximations.""",r"""For embedded submanifolds \(S,T\subset X\) meeting transversely and properly supported classical pseudodifferential operators \(P,Q\), the conormal distributions \(P\delta_S\) and \(Q\delta_T\) have a canonical product. Their wavefront sets lie in \(N^*S\setminus0\) and \(N^*T\setminus0\); transversality excludes opposing covectors over a common point. Singular support alone, without a conormal or wavefront restriction, is insufficient to state such a rule.""",['bott1966report'],area='distributions and microlocal analysis',correct='correct with missing hypotheses',match='partial',reconstruction=r"""The wavefront formulation is a modern reconstruction of the sufficient class, not terminology attributed to the notebook. Bott's exposition supplies the transverse-distribution regularization relevant to the fixed-point argument.""",development='annotated',confidence='medium')
item(69,'P000109','claim','The transverse delta product',r"""\(\delta(x_1)\delta(x_2)=\delta(x_1,x_2)\), accompanied by crossing lines and a comment that the graph meets the diagonal transversely.""",r"""In coordinates \((x_1,x_2,z)\), the product of the integration distributions on \(x_1=0\) and \(x_2=0\) is the distribution \(\phi\mapsto\int\phi(0,0,z)\,dz\), with the chosen coordinate densities. Tensor-product mollifiers give this limit. More generally, a change of transverse defining equations contributes the usual Jacobian determinant.""",['bott1966report'],area='distributions and microlocal analysis',development='annotated')
ev('Atiyah Bott fixed point formula November 1965 regularization Kotake Narasimhan','https://www.numdam.org/item/SB_1964-1966__9__265_0.pdf','read the result','Bott Expose 295, lecture November 1965; fixed-point and transverse-distribution argument match record 69. Bibliography cites Harvard notes fall 1964, preventing false novelty classification.','Printed pp. 265-270; theorem 2.2 and final fixed-point formula; references p. 270','69')
save()

# 70. Kazhdan coherent algebraic sheaves.
talk(70,'1965-11-15','D. A. Kazhdan','P000109-P000111','Coherent algebraic sheaves on affine varieties',r"""The Kazhdan heading lies on the lower part of P000109; his proof continues through the beginning of P000111. Principal affine opens, coherence of the structure sheaf, localization of sections, and affine acyclicity are presented in the tradition of Serre's \emph{Faisceaux alg\'ebriques coh\'erents}. An incomplete affineness-converse line is preserved as incomplete. \citep{serre1955faisceaux}""")
item(70,'P000109','construction','Principal affine opens and localization',r"""\(X_P=\{P\ne0\}\) forms a Zariski basis, with sections \(Q/P^n\). The notes say that \(X_P\) is again an affine space.""",r"""If \(X=\operatorname{Spec}A\) is an affine variety over a field and \(P\in A\), then \(D(P)=\operatorname{Spec}A_P\), and \(\Gamma(D(P),\mathcal O_X)=A_P\). It is affine, realized by \(Pt=1\) in \(X\times\mathbb A^1\), but need not be an affine space. For example \(D(x)\subset\mathbb A^1\) is \(\mathbb G_m\).""",['serre1955faisceaux'],area='algebraic geometry and sheaves',correct='false as written',reconstruction=r"""Here and below \(A\) is the coordinate ring of \(X\), a quotient of a polynomial ring in general.""",development='annotated')
item(70,'P000109','definition','Finite type and coherent algebraic sheaves',r"""An algebraic sheaf is an \(\mathcal O_X\)-module. Finite type means locally a quotient of a finite direct sum; coherence additionally requires every relation sheaf for a finite set of sections to be of finite type.""",r"""An \(\mathcal O_X\)-module \(\mathcal F\) is coherent if it is locally finitely generated and, for every open \(U\) and finite family of local sections, the kernel of the resulting map \(\mathcal O_U^r\to\mathcal F|_U\) is locally finitely generated. Finite generation alone is not the definition on an arbitrary ringed space.""",['serre1955faisceaux'],area='algebraic geometry and sheaves')
item(70,'P000109-P000110','theorem','Coherence of structure sheaves by Noetherianity',r"""The relation module of \((Q_1/P^n,\ldots,Q_r/P^n)\) is reduced to a kernel over \(k[x_1,\ldots,x_n]\), which is finitely generated by Hilbert's theorem.""",r"""A finitely generated algebra over a field is Noetherian. Kernels of maps between finite free modules are finitely generated, and localization commutes with their kernels. Consequently \(\mathcal O_X\) is coherent on an affine finite-type variety and, by locality, on every locally Noetherian variety.""",['serre1955faisceaux'],area='algebraic geometry and sheaves',reconstruction=r"""For a general affine variety replace the polynomial ring by its defining quotient; the kernel generates the relation sheaf, rather than being a fibre without localization.""",correct='correct with missing hypotheses')
item(70,'P000110','construction','Closed subvarieties and quotient sheaves',r"""For closed \(Y\subset X\), the ideal sheaf \(J_Y\) is coherent and \(\mathcal O_X/J_Y=\mathcal O_Y\).""",r"""For a closed immersion \(i:Y\hookrightarrow X\) of Noetherian varieties, the defining ideal sheaf \(\mathcal I_Y\) and the quotient \(\mathcal O_X/\mathcal I_Y\) are coherent; as sheaves on \(X\), the latter is \(i_*\mathcal O_Y\). The structure sheaf on \(Y\) itself is obtained by restriction to its own ringed space.""",['serre1955faisceaux'],area='algebraic geometry and sheaves',correct='correct with missing hypotheses',reconstruction=r"""The pushforward distinguishes the two underlying spaces suppressed in the notes.""")
item(70,'P000110-P000111','theorem','Global generation and acyclicity on an affine variety',r"""First the notes state vanishing for coherent sheaves, and later say that any sheaf is generated by sections and has trivial higher cohomology.""",r"""For \(X=\operatorname{Spec}A\), a quasi-coherent sheaf \(\widetilde M\) is generated by its global sections and satisfies \(H^q(X,\widetilde M)=0\) for \(q>0\). On a Noetherian affine variety, coherent sheaves correspond to finite \(A\)-modules. The assertion is not true for arbitrary sheaves.""",['serre1955faisceaux'],area='algebraic geometry and sheaves',correct='false as written',development='annotated',reconstruction=r"""The coherent or quasi-coherent hypothesis must be restored to the second formulation; it is already present in the preceding line.""")
item(70,'P000110-P000111','method','Computing cohomology with an affine cover',r"""Affine acyclicity permits calculation with an affine cover; the proof ends with the vanishing of cover cohomology for a principal-open cover \((X_{p_i})\).""",r"""For a separated variety and a finite affine cover, finite intersections are affine. The Cech complex of a quasi-coherent sheaf therefore computes its sheaf cohomology. On an affine scheme a finite principal-open cover has an exact augmented Cech complex for a quasi-coherent sheaf.""",['serre1955faisceaux'],area='algebraic geometry and sheaves',correct='correct with missing hypotheses',reconstruction=r"""Separatedness, quasi-coherence and the acyclicity of intersections are the hypotheses used by the Cech-to-derived comparison.""")
item(70,'P000110','remark','The unfinished converse to affine acyclicity',r"""The line labelled Chevalley's theorem stops at \(H^i=0\Longrightarrow\), with no consequent.""",r"""The natural comparison is Serre's affineness criterion: for a Noetherian scheme, vanishing of \(H^q(X,\mathcal F)\) for every quasi-coherent \(\mathcal F\) and every \(q>0\) characterizes affineness. The notebook does not give the quantifiers or the conclusion; it cannot establish which variant or attribution the speaker intended.""",['serre1955faisceaux'],area='algebraic geometry and sheaves',cl='F',correct='not determinable',match='partial',confidence='medium',reconstruction=r"""The affineness criterion is offered only as a historically and contextually natural reconstruction, not as a recovered missing phrase.""",fate=r"""Serre's affine theory supplies a close comparison, but the unfinished sentence is insufficient for an exact identification of a separate theorem called Chevalley's. \citep{serre1955faisceaux}""",status=r"""As of 9 November 2026, the standard affineness criterion is settled; the exact assertion of this unfinished occurrence remains unidentifiable. No new open-problem entry is created.""")
item(70,'P000110','theorem','Hilbert Nullstellensatz and the coordinate ring',r"""If \(P\) vanishes on the variety of an ideal \(J\), then \(P^k\in J\); the notes then identify the ring of sections with \(A=k[x_1,\ldots,x_n]\).""",r"""Over an algebraically closed field \(k\), the strong Nullstellensatz gives \(I(V(J))=\sqrt J\) for \(J\subset k[x_1,\ldots,x_n]\). If \(X\) is a reduced affine variety, \(\Gamma(X,\mathcal O_X)=k[x_1,\ldots,x_n]/I(X)\), not the ambient polynomial ring unless \(X=\mathbb A^n\).""",['serre1955faisceaux'],area='algebraic geometry and sheaves',correct='correct with missing hypotheses',reconstruction=r"""The field condition and the quotient implicit in the symbol \(A\) are stated explicitly.""",development='annotated')
item(70,'P000110','lemma' if False else 'claim','A section supported on a principal divisor is killed by a power',r"""Lemma 1: if a section \(s\) of a coherent sheaf on affine \(X\) vanishes on \(X_P\), then \(P^m s=0\) for some \(m\).""",r"""For \(\mathcal F=\widetilde M\) on \(\operatorname{Spec}A\), a global section \(s\in M\) restricts to zero in \(M_P\) exactly when \(P^m s=0\) for some nonnegative integer \(m\). The localized-module criterion proves the statement, and in fact does not require finite generation of \(M\).""",['serre1955faisceaux'],area='algebraic geometry and sheaves',development='annotated')
item(70,'P000110','remark','The ideal of the origin on the affine line',r"""The notes identify \(k[x]\) with germs of polynomials vanishing at zero and call the quotient one dimensional.""",r"""The ideal of global polynomials vanishing at zero is \((x)\subset k[x]\), with \(k[x]/(x)\simeq k\). At the stalk the corresponding ideal is \((x)k[x]_{(x)}\subset k[x]_{(x)}\). The ideal, ambient ring and local ring must be distinguished.""",['serre1955faisceaux'],area='algebraic geometry and sheaves',correct='false as written',development='annotated')
item(70,'P000110-P000111','claim','Clearing denominators in a coherent subsheaf',r"""Lemma 2: \(\mathcal F\subset\mathcal O_X^n\); a section over \(X_P\) extends to \(X\) after multiplication by a sufficiently high power of \(P\).""",r"""Let \(X=\operatorname{Spec}A\) be Noetherian and \(\mathcal F\subset\mathcal O_X^n\) coherent. For \(s\in\Gamma(D(P),\mathcal F)\), first clear its coordinates in \((A_P)^n\), obtaining \(t\in A^n\). The image of \(t\) in \(\Gamma(X,\mathcal O_X^n/\mathcal F)\) vanishes after localization and is killed by a further power of \(P\); hence that power times \(t\) lies in \(\Gamma(X,\mathcal F)\).""",['serre1955faisceaux'],area='algebraic geometry and sheaves',development='annotated',reconstruction=r"""The sentence on P000111 saying that the cleared section may fail to belong to \(\mathcal O_X^n\) must mathematically refer to failure to belong to \(\mathcal F\). The ambient free module already contains the cleared vector.""",correct='correct with missing hypotheses')
ev('Serre Faisceaux algébriques cohérents 1955 affine coherent sheaves localization','https://www.college-de-france.fr/media/jean-pierre-serre/UPL5435398796951750634_Serre_FAC.pdf','read the result','Author-institution full text opened; affine global generation, vanishing, coherent modules and localization match Kazhdan exposition.','Introduction pp. 197-198 and chapter II on affine varieties','70')
save()

# 71. Gelfand: Bott--Chern, value distribution, and connections.
talk(71,'1965-11-22','I. M. Gelfand','P000111-P000113','Value distribution and Chern forms after Bott and Chern',r"""The dated heading on P000111 explicitly names Bott--Chern, \emph{Acta Mathematica} 114 (1965). Gelfand moves from Picard and Nevanlinna theory to spectral boundary conditions and an explicitly doubtful Banach-space extension, then introduces bundle-valued differential forms, connections, curvature and Chern forms. The record ends immediately before the Arnold heading on P000113. \citep{bottchern1965hermitian}""")
item(71,'P000111','theorem','Picard omission and the Nevanlinna defect relation',r"""The notes say that a meromorphic quotient \(a(z)/b(z)\) omits at most two values and that the sum of its defects is at most two.""",r"""For a nonconstant meromorphic function \(f:\mathbb C\to\mathbb P^1\), at most two points of \(\mathbb P^1\) are omitted. With the usual characteristic \(T(r,f)\) and counting functions, the Nevanlinna defects satisfy \(\sum_{a\in\mathbb P^1}\delta(a,f)\le2\). The ratio model uses a reduced pair of entire functions, with no common zero; the associated projective curve is the invariant object.""",['bottchern1965hermitian'],area='complex analysis and value distribution',correct='correct with missing hypotheses',reconstruction=r"""Nonconstancy and the projective interpretation exclude the immediate constant-function counterexample.""")
item(71,'P000111','claim','Higher-dimensional hyperplane omission requires general position',r"""An entire curve \((a,b,c)\) in three-dimensional space is said to meet every plane through zero except possibly three; a finite number is asserted in dimension \(n\).""",r"""For a linearly nondegenerate holomorphic curve \(f:\mathbb C\to\mathbb P^{n-1}\), a collection of omitted hyperplanes in general position has at most \(n\) members. The general-position requirement concerns the collection: any \(n\) defining linear forms are independent. Without nondegeneracy even a constant projective curve avoids infinitely many hyperplanes, so the notebook's unqualified formulation is false.""",['bottchern1965hermitian'],area='complex analysis and value distribution',correct='correct with missing hypotheses',reconstruction=r"""Linear nondegeneracy and general position are the precise classical hypotheses supplied by the cited value-distribution context; no unrestricted total-hyperplane bound is claimed here.""",development='annotated')
item(71,'P000111','construction','The endpoint analytic curve for Sturm--Liouville problems',r"""The equation is \(-y''+p(x)y=\lambda y\) on \([0,\pi]\). One margin has \(y(0)=y'(0)=0\), but the subsequent displayed solution is normalized by \(y(0,\lambda)=0,\ y'(0,\lambda)=1\).""",r"""For a fixed integrable potential \(p\), the solution with initial data \((0,1)\) is entire in \(\lambda\), as are \(y(\pi,\lambda)\) and \(y'(\pi,\lambda)\). For fixed \((a,b)\ne(0,0)\), the separated right condition \(a y'(\pi)+b y(\pi)=0\) gives the characteristic function \(a y'(\pi,\lambda)+b y(\pi,\lambda)\). Its zeros are precisely the eigenvalues for the left Dirichlet condition. Initial data \((0,0)\) instead produce only the zero solution.""",['bottchern1965hermitian'],area='spectral theory and value distribution',correct='false as written',match='thematic only',verification='indirect',reconstruction=r"""Integrability of the fixed potential and nonzero boundary coefficients are sufficient standard assumptions. The normalization repair is internal: the scan itself supplies \(y'(0,\lambda)=1\) below the erroneous margin.""",development='annotated',fate=r"""The differential-equation observation is classical and is independently checked by the Volterra integral equation; the cited Bott--Chern paper supplies the surrounding value-distribution theme, not this spectral argument. \citep{bottchern1965hermitian}""")
item(71,'P000111-P000112','question','A value-distribution route to spectral completeness',r"""Gelfand asks how general considerations about an analytic curve in a function space could give completeness. A theorem for a Banach-space curve missing only finitely many hyperplanes is proposed with \ru{возм., неверно}.""",r"""The notebook specifies neither a Banach space, a topology of completeness, nor a class of hyperplanes or curves sufficient to identify a spectral-completeness theorem. Moreover, a literal finite-omission assertion fails even for a linearly nondegenerate entire curve in \(\ell^2\): \[F(z)=(1,e^z,e^{2z}/2!,e^{3z}/3!,\ldots).\] Every coordinate is nonzero, so every coordinate hyperplane is omitted. If a continuous linear functional annihilates \(F\), the entire power series in \(w=e^z\) vanishes on \(\mathbb C^*\), so all its coefficients vanish.""",['bottchern1965hermitian'],area='spectral theory and value distribution',cl='F',correct='not determinable',match='thematic only',verification='indirect',development='annotated',reconstruction=r"""The displayed Hilbert-space counterexample and its linear nondegeneracy proof are this task's annotation of the broad proposed assertion. They do not purport to refute an unspecified stronger hypothesis that Gelfand might have intended.""",fate=r"""Bott--Chern does not state this Banach-space completeness theorem. Its finite-dimensional setting cannot be promoted to one. The notes themselves signal doubt; the intended spectral question remains insufficiently specified. \citep{bottchern1965hermitian}""",status=r"""As of 9 November 2026, the raw finite-omission proposal has the explicit counterexample above. A precise additional-hypothesis completeness problem has not been recovered, so this is F rather than an allegedly neglected open problem.""",confidence='medium')
item(71,'P000112','question','Distribution of simultaneous zeros in several complex variables',r"""The notes ask about the zeros of \(n\) functions in \(n\) variables and say that no satisfactory analogue of Nevanlinna theory exists.""",r"""This is a research programme, not a single quantified conjecture: the source does not specify the domain, exhaustion, growth hypotheses, target geometry or defect inequality. Bott--Chern treats zero distribution of holomorphic sections in Hermitian bundles, providing a concrete portion of the programme. No theorem covering every possible meaning of satisfactory theory can be formulated from the sentence.""",['bottchern1965hermitian'],area='complex analysis and value distribution',cl='F',correct='not determinable',match='partial',reconstruction=r"""The exact subject of the named paper supplies context without supplying absent hypotheses.""",fate=r"""The explicitly cited 1965 paper already develops one version of the several-variable zero-distribution theory. Its scope does not turn this broad remark into a settled or unsettled universal conjecture. \citep{bottchern1965hermitian}""",status=r"""As of 9 November 2026, substantial several-variable value-distribution theories exist, but the notebook sentence has no precise residual question. No problem-index entry is assigned.""",confidence='medium')
item(71,'P000112','construction','Bundle-valued forms and a connection',r"""\(A(X,E)=A(X)\otimes\Gamma(E)\), followed by a tensor-base entry read as \(A^0(E)\); the connection satisfies \(D(fs)=df\,s+fDs\).""",r"""For a smooth finite-rank vector bundle \(E\to X\), \(A^\bullet(X,E)=\Omega^\bullet(X)\otimes_{C^\infty(X)}\Gamma(E)\). A connection is a real- or complex-linear map \(D:\Gamma(E)\to\Omega^1(X,E)\) with the displayed Leibniz rule. It extends to bundle-valued forms by \(D(\alpha\otimes s)=d\alpha\otimes s+(-1)^{\deg\alpha}\alpha\wedge Ds\).""",['bottchern1965hermitian'],area='characteristic classes and differential geometry',correct='correct with missing hypotheses',reconstruction=r"""The tensor base is \(A^0(X)=C^\infty(X)\), as the very next tensor formula in the notes confirms. The graded extension is made explicit because its sign controls subsequent curvature calculations.""",development='annotated')
item(71,'P000112','definition','Curvature in the notebook frame convention',r"""For \(Ds_i=\sum_j\theta_{ij}s_j\), the curvature is written \(K=d\theta-\theta\wedge\theta\). Matrix multiplication explains why \(\theta\wedge\theta\) need not vanish.""",r"""Writing the frame as the column \(s=(s_i)\) with \(Ds=\theta s\) and extending \(D\) by the graded Leibniz rule gives \(D^2s=(d\theta-\theta\wedge\theta)s\). Thus \(K\) is a matrix of two-forms representing the curvature in this frame convention. The minus sign is consistent and should not be replaced by the plus sign used with another matrix convention.""",['bottchern1965hermitian'],area='characteristic classes and differential geometry',development='annotated')
item(71,'P000112-P000113','construction','Chern forms, normalization and cohomology classes',r"""The displayed determinant on P000112 has \(2\pi/i\), and the text calls the result closed two-forms; P000113 says that it is independent of the connection.""",r"""For a complex vector bundle with connection, the total Chern form in the preceding convention is \[c(E,D)=\det\left(I+\frac{i}{2\pi}K\right)=1+c_1(E,D)+\cdots+c_r(E,D),\qquad c_j\in\Omega^{2j}(X).\] These forms are closed. Their de Rham cohomology classes are independent of the connection; their actual differential-form representatives generally vary with it.""",['bottchern1965hermitian'],area='characteristic classes and differential geometry',correct='false as written',development='annotated',reconstruction=r"""The reciprocal coefficient on P000112 is a notebook mathematical error, not a transcription correction: the scan has it, whereas P000116 and P000119 give \(i/(2\pi)\). The distinction between a form and its class repairs the independence claim.""")
item(71,'P000113','theorem','Change of frame and invariant determinant',r"""\(s'=As\) gives \(dA+A\theta=\theta'A\) and \(AK=K'A\). The intermediate differentiated line lacks a prime and has the wrong graded sign.""",r"""For an invertible matrix \(A\) of smooth functions, \[\theta'=dA\,A^{-1}+A\theta A^{-1},\qquad K'=AKA^{-1}.\] Differentiating the first frame identity requires \(dA\wedge\theta+A\,d\theta=d\theta' A-\theta'\wedge dA\). Conjugacy of \(K\), together with commutativity of even scalar forms, makes \(\det(I+tK)\) independent of frame.""",['bottchern1965hermitian'],area='characteristic classes and differential geometry',correct='false as written',development='annotated',reconstruction=r"""The displayed conjugacy is correct. The defective intervening differentiated identity is corrected as a mathematical annotation after checking the scan; it is not silently replaced in the source transcription.""")
ev('Bott Chern Hermitian vector bundles equidistribution zeroes 1965 Acta 114','https://webhomes.maths.ed.ac.uk/~v1ranick/papers/bottchern.pdf','read the result','Full 42-page primary paper opened. Value-distribution introduction and connection/Chern-form sections match Gelfand. Metric compatibility alone is not the unique-connection theorem: holomorphic compatibility is also required.','Introduction pp. 71-74; section 2 pp. 75-80; Proposition 3.2 p. 81; later zero-distribution sections','71,73,75')
save()

# 72. Arnold on singularities.
talk(72,'1965-11-22','V. I. Arnold','P000113-P000116','Singularities and stability of differentiable mappings',r"""Arnold's heading begins below Gelfand's frame calculation on P000113; the final comment on a continuous smooth invariant extends onto the first lines of P000116. The record distinguishes Morse, fold and cusp singularities, discusses rank strata and Boardman symbols, and reports then-current claims of Thom and Mather. Arnold's 1968 lectures contain especially close matches, but their later publication is not evidence that the older Whitney and Morse results originated in this seminar. \citep{arnold1968singularities,boardman1967singularities,mather1971nice}""")
item(72,'P000113','definition','Left--right equivalence and structural stability of map germs',r"""The source studies \(f:M^m\to N^n\), or \((\mathbb R^m,0)\to(\mathbb R^n,0)\), up to changes of variables in source and target, and asks whether small perturbations remain equivalent.""",r"""Two germs are smoothly left--right equivalent when \(g=k\circ f\circ h^{-1}\) for local diffeomorphisms \(h,k\). Local stability allows the singular point to move under perturbation. For a global map, stability means that an open neighbourhood in the Whitney smooth topology lies in its orbit under source and target diffeomorphisms. A topological variant replaces the equivalences by homeomorphisms.""",['arnold1968singularities'],area='singularity theory',reconstruction=r"""Local stability with movable source/target points must be distinguished from equivalence of germs fixing the origin and from global stability.""",correct='correct with missing hypotheses')
item(72,'P000113','theorem','Morse normal form and genericity',r"""For \(n=1\), nondegenerate \(d^2f\) gives a quadratic form, classified by index and signature; generic critical points are isolated, and the relevant set is open and dense for compact source.""",r"""If \(df_p=0\) and the Hessian is nonsingular, smooth local coordinates give \(f=f(p)-x_1^2-\cdots-x_\lambda^2+x_{\lambda+1}^2+\cdots+x_m^2\). Morse functions form an open dense subset of \(C^\infty(M,\mathbb R)\) for compact \(M\). Global left--right stability additionally requires pairwise distinct critical values; nondegenerate critical points alone supply local stability.""",['arnold1968singularities'],area='singularity theory',correct='correct with missing hypotheses',development='annotated')
item(72,'P000113','theorem','Whitney fold and cusp normal forms for surface maps',r"""The three displayed models are regular, fold \((x_1^2,x_2)\), and cusp \((x_1,x_2^3-x_1x_2)\); the source attributes approximation by these types to Whitney (1955).""",r"""A generic smooth map between surfaces has only regular points, folds and cusps; its critical set is a smooth curve, with isolated cusp points. The listed normal forms represent the local stable types. For global stability of a proper map, additional multisingularity conditions are needed: distinct fold branches meet transversely, only double fold intersections occur, and cusp images are separated from other critical images.""",['arnold1968singularities','malgrange1966ideals'],area='singularity theory',correct='correct with missing hypotheses',reconstruction=r"""The global transversality conditions are not supplied by the list of local models. They are stated to prevent reading a local classification as a complete global criterion.""")
item(72,'P000114','claim','Cusp critical curve and its image',r"""For \((y_1,y_2)=(x_1,x_2^3-x_1x_2)\), the determinant is \(3x_2^2-x_1\). The source then writes \(y_2^2=-y_1^3\), \(y_1>0\), and initially calls the origin a fold.""",r"""The critical curve is \((x_1,x_2)=(3t^2,t)\), mapped to \((y_1,y_2)=(3t^2,-2t^3)\). Thus \(27y_2^2=4y_1^3\). The origin is a cusp; every other nearby critical point is a fold. The family \(t\mapsto t^3-Ct\) is strictly increasing for \(C<0\), and has two critical points for \(C>0\), producing the familiar one-versus-three inverse-image regions.""",['arnold1968singularities'],area='singularity theory',correct='false as written',development='annotated',reconstruction=r"""The signs and coefficients follow directly by substitution, independently of publication identification. Both erroneous statements are visible in the scan; the later line correctly says that points away from zero are folds.""")
item(72,'P000114','problem','The perturbation of a complex square by a conjugate-linear term',r"""The explicit exercise is \(z\mapsto z^2+\varepsilon\overline z\), with \(\varepsilon\ne0\), and the predicted singularities are folds and cusps.""",r"""As a real map of the plane, \(F_\varepsilon\) has Jacobian \(4|z|^2-|\varepsilon|^2\). Its critical locus is the circle \(|z|=|\varepsilon|/2\). Rotations and positive rescalings reduce the caustic to \(w(t)=\tfrac14e^{2it}+\tfrac12e^{-it}\): its derivative vanishes exactly at \(e^{3it}=1\), giving three ordinary cusps and folds elsewhere. The critical image is a three-cusped hypocycloid.""",['arnold1968singularities'],area='singularity theory',development='annotated',fate=r"""Arnold's 1968 exposition, Example 6, gives exactly this perturbation and its three-cusp picture. It is a standard explicit exercise, not a residual open problem. \citep{arnold1968singularities}""",reconstruction=r"""The determinant, parameterization and cusp test are independently computed in this task. A nonzero complex \(\varepsilon\) is reduced to the same model by source/target rotations.""")
item(72,'P000114','claim','Rank strata and their expected codimension',r"""The notes discuss the independent minors of a rectangular rank-\(r\) matrix and call the corresponding \(\Sigma_r\) smooth submanifolds of the source.""",r"""The rank-exactly-\(r\) locus in \(\operatorname{Hom}(\mathbb R^m,\mathbb R^n)\) is smooth of codimension \((m-r)(n-r)\). For a map \(f\), its inverse image under the first jet is a smooth source submanifold of this codimension when the jet section is transverse to that matrix-rank stratum. Arbitrary maps need not have smooth rank loci.""",['boardman1967singularities','arnold1968singularities'],area='singularity theory',correct='correct with missing hypotheses',reconstruction=r"""The generic transversality condition separates a smooth universal jet stratum from its possibly singular inverse image.""",development='annotated')
item(72,'P000114-P000115','construction','Iterated coranks and the fold--cusp Boardman symbols',r"""A decreasing rank sequence is introduced on P000114; P000115 changes to a corank convention, calls \(\Sigma_0\) regular, and labels a cusp \(\Sigma_{10}\).""",r"""With Boardman's convention, the first entry is \(\dim\ker df\), and successive entries are obtained by intrinsic derivative or Jacobian-ideal extensions. For a generic surface map, a fold has symbol \((1,0)\), while a cusp has \((1,1,0)\). Successively restricting to smooth rank strata is an explanatory model only where the relevant transversality holds; it is not a definition for every germ.""",['boardman1967singularities','arnold1968singularities'],area='singularity theory',correct='false as written',development='annotated',reconstruction=r"""The notation switch and incorrect cusp label are notebook errors. The corrected cusp symbol is also explicit in Arnold's later exposition, section 6.""")
item(72,'P000115','theorem','Boardman strata in jet space and generic transversality',r"""The notes name Boardman and replace the naive repeated-rank construction by a decomposition in spaces of truncated Taylor series.""",r"""For every admissible finite Boardman symbol \(I\), the universal stratum \(\Sigma^I\) is a smooth locally closed submanifold of a sufficiently high jet space, with a universal codimension. A jet section transverse to it has a smooth inverse-image stratum of that codimension. Smooth maps can be approximated in the fine smooth topology by maps transverse to all these strata.""",['boardman1967singularities'],area='singularity theory',cl='B',fate=r"""Boardman's Theorems 6.1--6.3 give the precise general construction and transversality statements in 1967. This is a substantive later publication match, not merely a shared title. \citep{boardman1967singularities}""",correct='correct with missing hypotheses',reconstruction=r"""The finite-jet order, admissibility and transversality qualifications are supplied from the primary statement.""")
item(72,'P000115','method','Smooth, analytic and formal equivalence are different categories',r"""The record compares \(C^\infty\) germs, analytic germs and formal power series. Formal coordinate changes have invertible first derivative.""",r"""A formal map germ fixing zero is invertible under formal composition exactly when its linear part is invertible. Analytic changes also require convergence; smooth changes may contain flat terms invisible to every finite jet and to the full Taylor series. Consequently equality or equivalence of Taylor series alone does not establish smooth or analytic equivalence without a finite-determinacy or convergence theorem.""",['arnold1968singularities','malgrange1966ideals'],area='singularity theory',correct='correct with missing hypotheses',development='annotated')
item(72,'P000115-P000116','claim','Smooth moduli and the incompleteness of Boardman symbols',r"""The notes mention a \(\mathbb R^9\to\mathbb R^9\) example, infinitely many or continuous invariants in larger dimensions, and a smooth invariant that is not topological.""",r"""Boardman symbols are coarse invariants and do not classify left--right orbits. Thom's quadratic-map examples show continuous moduli of smooth equivalence and failure of density of smooth stable maps beginning at the pair \((9,9)\). Such smooth moduli need not be invariants of topological equivalence. The notes do not display a particular germ or prove that one germ has an infinite list of independent moduli.""",['arnold1968singularities','mather1971nice'],area='singularity theory',cl='B',fate=r"""Arnold's 1968 section 3 supplies the quadratic-moduli argument and Mather's nice-dimension calculation gives the precise density boundary. The loose phrase about infinitely many invariants is matched only partially. \citep{arnold1968singularities,mather1971nice}""",correct='correct with missing hypotheses',match='partial',confidence='medium',reconstruction=r"""Continuous moduli and infinitely many equivalence classes are not conflated with infinitely many independent invariants of a specified germ.""")
item(72,'P000115','claim','Thom topological classification outside infinite codimension',r"""Thom is said to remove an infinite-codimension part of the space of power series so that the remainder is topologically stable; an unpublished proof is discussed.""",r"""The identifiable historical formulation is a decomposition of germs into countably many finite-codimension pieces consisting of topologically equivalent germs, with an exceptional part of infinite jet-codimension. This is distinct from saying that every such germ is individually an open orbit. A related global theorem asserts density of topologically stable maps from a compact smooth manifold to any smooth manifold, in every dimension pair.""",['arnold1968singularities','mather1970topological'],area='singularity theory',cl='B',fate=r"""Arnold's 1968 Theorem 4 repeats the germ formulation and still marks its proof unpublished. Mather's 1970 notes set up the stratification and isotopy machinery and identify the compact-source density theorem as their aim. These opened sources give a partial, not exact, match to the notebook's compressed assertion. \citep{arnold1968singularities,mather1970topological}""",correct='correct with missing hypotheses',match='partial',confidence='medium',reconstruction=r"""The distinction between an equisingularity stratum and an open stable orbit is essential. No blanket theorem for differential equations is inferred from this map-germ statement.""",status=r"""As of 9 November 2026, topological stability of smooth maps belongs to the established Thom--Mather theory. The exact formulation and proof represented by the 1965 oral report cannot be recovered solely from the notebook; this entry does not claim to have read an original unpublished proof.""")
item(72,'P000115','theorem','Infinitesimal stability and the source--target linearization',r"""For every variation \(\varphi\), the equation \(\varphi(x)=f'(x)h(x)+k(y)\) should be solvable; this is attributed to Mather, followed by the remark that the proof is incorrect.""",r"""For a proper smooth map \(f:M\to N\), infinitesimal stability is the surjectivity of \[\Gamma(TM)\oplus\Gamma(TN)\longrightarrow\Gamma(f^*TN),\qquad(h,k)\longmapsto df(h)+k\circ f.\] In Mather's smooth theory it is equivalent to stability. Properness, the topology of maps, and the global or multigerm setting matter; an arbitrary Frechet-space inverse-function theorem does not prove the assertion.""",['mather1969stability','arnold1968singularities'],area='singularity theory',cl='B',fate=r"""Mather's 1969 paper establishes the sufficient direction; Arnold's 1968 exposition reports the subsequently successful smooth proof and develops an analytic local argument. The 1965 criticism cannot be transferred to the final theorem. \citep{mather1969stability,arnold1968singularities}""",correct='correct with missing hypotheses',verification='publisher metadata checked',reconstruction=r"""The proper-map formulation is a modern precise version. Mather's original article was verified at publisher-metadata level; the later Arnold exposition was read, so the exact Mather proof is not claimed as checked.""")
item(72,'P000115','remark','The unreadable finite-degree test for stability',r"""The parenthesis says it suffices to test polynomial \(\varphi\) of degree equal to a dimension, followed by an overwritten \(\ell\)- or \(N\)-like sign.""",r"""No numerical finite-jet threshold can be recovered. Finite determinacy and algebraic tests for stability do exist, but they depend on the relevant local algebra, the source and target dimensions, the equivalence group, and the distinction between germs and multigerms. None of those choices identifies the missing integer here.""",['mather1969stability','arnold1968singularities'],area='singularity theory',cl='F',correct='not determinable',match='thematic only',verification='unresolved lead',confidence='low',fate=r"""The sources confirm the surrounding finite-determinacy programme, not the unreadable bound. \citep{mather1969stability,arnold1968singularities}""",status=r"""As of 9 November 2026, this occurrence remains an unresolved reading and identification problem, not an open finite-determinacy conjecture.""")
item(72,'P000115','claim','The low-dimensional stability range and generic immersions',r"""The source lists \(\mathbb R^2\to\mathbb R^2,\mathbb R^3\), calls the \(\mathbb R^4\) target case unknown, says \(\mathbb R^5\) has no singularities, and gives density through \(m=n=8\).""",r"""Mather's nice-dimension criterion gives density of stable proper maps for the pairs \((2,2),(2,3),(2,4),(2,5)\), and for equal dimensions \((m,m)\) exactly when \(m\le8\). Generic maps of a surface into a four-manifold are already immersions locally: the rank-drop stratum has codimension \(4-2+1=3>2\); target dimension five also eliminates generic double points. An immersion and an embedding must not be identified.""",['mather1971nice','boardman1967singularities'],area='singularity theory',cl='B',correct='correct with missing hypotheses',development='annotated',fate=r"""The exact density region is calculated in Mather's paper. The opened Russian translation reproduces the criterion and explicitly warns about nonproper maps. The 1965 unknown-status annotation is historical, not current. \citep{mather1971nice}""",reconstruction=r"""The generic-immersion codimension calculation is independent. It shows that the notebook's \(\mathbb R^4\) uncertainty cannot safely be interpreted as uncertainty about absence of local rank singularities.""")
